def current_rows(events):
    latest = {}
    for event in events:
        key = event['id']
        current = latest.get(key)
        if current is None or (event['event_time'], event['seq']) > (current['event_time'], current['seq']):
            latest[key] = event

    result = []
    for id_ in sorted(latest):
        ev = latest[id_]
        if ev['op'] != 'D':
            result.append({'id': id_, 'value': ev['value']})
    return result
