import heapq

def stable_toposort(graph):
    n = len(graph)
    index = {node: i for i, node in enumerate(graph.keys())}
    in_degree = {node: 0 for node in graph}
    adj = {node: [] for node in graph}

    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep}")
            in_degree[node] += 1
            adj[dep].append(node)

    heap = []
    for node in graph:
        if in_degree[node] == 0:
            heapq.heappush(heap, (index[node], node))

    order = []
    while heap:
        _, node = heapq.heappop(heap)
        order.append(node)
        for dependent in adj[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, (index[dependent], dependent))

    if len(order) != n:
        raise ValueError("Cycle detected")

    return order
```

