def schema_drift(expected, actual):
    drift = []

    def collect_leaf_paths(obj, prefix):
        if not isinstance(obj, dict):
            return [prefix]
        paths = []
        for k, v in obj.items():
            new_prefix = f"{prefix}.{k}" if prefix else k
            paths.extend(collect_leaf_paths(v, new_prefix))
        return paths

    def compare(e, a, path):
        # missing in actual
        for key in e:
            new_path = f"{path}.{key}" if path else key
            if key not in a:
                paths = collect_leaf_paths(e[key], new_path)
                drift.extend(paths)
            else:
                ev, av = e[key], a[key]
                if isinstance(ev, dict) and isinstance(av, dict):
                    compare(ev, av, new_path)
                elif ev != av:  # string vs string or dict vs string
                    drift.append(new_path)

        # extra in actual
        for key in a:
            new_path = f"{path}.{key}" if path else key
            if key not in e:
                paths = collect_leaf_paths(a[key], new_path)
                drift.extend(paths)

    compare(expected, actual, "")
    return sorted(drift)
