def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be positive")

    batches = []
    current_batch = []
    current_total = 0

    for item in items:
        partition, row_count = item

        if row_count > max_rows:
            # close the current batch if any
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_total = 0
            # this item must be alone
            batches.append([item])
        else:
            if current_total + row_count <= max_rows:
                current_batch.append(item)
                current_total += row_count
            else:
                # close current batch and start a new one
                if current_batch:
                    batches.append(current_batch)
                current_batch = [item]
                current_total = row_count

    # append any remaining items
    if current_batch:
        batches.append(current_batch)

    return batches
