def merge_payload_ranges(items):
    # Validate and convert to list of lists for non-mutation
    valid_items = []
    for start, end, payload in items:
        if start > end:
            raise ValueError(f"Invalid range: start {start} > end {end}")
        valid_items.append([start, end, payload])

    # Sort by start, then by end
    valid_items.sort(key=lambda x: (x[0], x[1]))

    if not valid_items:
        return []

    merged = [valid_items[0]]
    for current in valid_items[1:]:
        last = merged[-1]
        # Merge if same payload and overlapping or touching
        if current[2] == last[2] and current[0] <= last[1] + 1:
            # Merge: update the end of last to max of both ends
            if current[1] > last[1]:
                last[1] = current[1]
        else:
            # Cannot merge, add as new range
            merged.append(current)

    return merged
